{
  "title": "Checkout Service",
  "uid": "checkout-overview",
  "refresh": "30s",
  "time": {"from": "now-6h", "to": "now"},
  "templating": {
    "list": [
      {"name": "namespace", "type": "query", "query": "label_values(http_requests_total, namespace)"}
    ]
  },
  "panels": [
    {
      "title": "Request rate",
      "type": "timeseries",
      "targets": [{"expr": "sum(rate(http_requests_total{service=\"checkout\",namespace=\"$namespace\"}[5m]))"}],
      "fieldConfig": {"defaults": {"unit": "reqps"}}
    },
    {
      "title": "Error ratio",
      "type": "timeseries",
      "targets": [{"expr": "sum(rate(http_requests_total{service=\"checkout\",namespace=\"$namespace\",status=~\"5..\"}[5m])) / sum(rate(http_requests_total{service=\"checkout\",namespace=\"$namespace\"}[5m]))"}],
      "fieldConfig": {"defaults": {"unit": "percentunit"}}
    },
    {
      "title": "p99 latency",
      "type": "timeseries",
      "targets": [{"expr": "histogram_quantile(0.99, sum by (le) (rate(http_request_duration_seconds_bucket{service=\"checkout\",namespace=\"$namespace\"}[5m])))"}],
      "fieldConfig": {"defaults": {"unit": "s"}}
    }
  ]
}
